// Everything this turn needs, in one place. The log lives in n8n's own workflow data, so there is no database
// to set up for a conversation history.
//
// Read what arrived, not a node by name: reaching back to `$('Telegram Trigger')` would make this impossible
// to test without Telegram and would break the moment you swapped the trigger for a webhook. Settings passes
// the message through, so everything needed is on one item.
const cfg = $input.first().json;
const msg = cfg.message || {};
const chatId = String(msg.chat?.id ?? '');
if (!chatId) { throw new Error('No chat id on the Telegram update — nothing to reply to.'); }

const store = $getWorkflowStaticData('global');
store.chats = store.chats || {};
const chat = store.chats[chatId] || (store.chats[chatId] = { turns: [] });
const keep = Math.max(2, Number(cfg.history_turns) || 10);
const history = chat.turns.slice(-keep);

return [{ json: {
  chatId,
  text: String(msg.text ?? ''),
  who: [msg.from?.first_name, msg.from?.last_name].filter(Boolean).join(' ') || msg.from?.username || 'customer',
  history,
  history_text: history.map(t => `${t.who}: ${t.text}`).join('\n') || '(nothing yet)',
}}];

// One AI node, three providers. Change `ai_provider` in Settings and nothing else moves.
// The request shapes come from each provider's own docs; only the Ollama path has been run on this machine.
const cfg = $('Settings').first().json;
const turn = $input.first().json;

const prompt = String(cfg.prompt)
  .replaceAll('{{BUSINESS}}', String(cfg.business_name))
  .replaceAll('{{KNOWLEDGE}}', String(cfg.knowledge))
  .replaceAll('{{HISTORY}}', String(turn.history_text))
  .replaceAll('{{MESSAGE}}', String(turn.text));

const provider = String(cfg.ai_provider || 'ollama').toLowerCase();
const model = String(cfg.ai_model || '');
let url, headers = { 'content-type': 'application/json' }, body;

if (provider === 'ollama') {
  url = `${String(cfg.ollama_url || 'http://127.0.0.1:11434').replace(/\/$/, '')}/api/chat`;
  body = { model, stream: false, format: 'json', messages: [{ role: 'user', content: prompt }] };
} else if (provider === 'openai') {
  // No key here, and none in Settings. n8n's creator hub forbids a key typed into a workflow, and it is the
  // right rule: a template is shared, and anything in it is shared with it. The key rides on the credential
  // you pick on the "Ask the AI" node, which n8n stores encrypted and never exports.
  url = 'https://api.openai.com/v1/chat/completions';
  body = { model, response_format: { type: 'json_object' }, messages: [{ role: 'user', content: prompt }] };
} else if (provider === 'anthropic') {
  url = 'https://api.anthropic.com/v1/messages';
  headers['anthropic-version'] = '2023-06-01';
  body = { model, max_tokens: 700, messages: [{ role: 'user', content: prompt }] };
} else {
  throw new Error(`ai_provider is "${provider}" — it must be ollama, openai or anthropic.`);
}
return [{ json: { url, headers, body, provider } }];

const cfg = $('Settings').first().json;
const turn = $('Load the conversation').first().json;
const provider = $('Build the AI request').first().json.provider;
const res = $input.first().json;
const cannot = String(cfg.cannot_answer_message || 'Thanks for your message. Someone will get back to you here.');

let raw = '';
try {
  if (provider === 'ollama') raw = res.message?.content ?? '';
  else if (provider === 'openai') raw = res.choices?.[0]?.message?.content ?? '';
  else if (provider === 'anthropic') raw = res.content?.[0]?.text ?? '';
} catch (e) { raw = ''; }

// An unreadable reply is not a reason to guess. Each of these says which it was, so a buyer reading their own
// executions can tell a model problem from a wiring problem.
let out;
if (!raw || !String(raw).trim()) {
  out = { answered: false, reason: 'the AI returned nothing', reply: cannot, machine_failed: true };
} else {
  try {
    const text = String(raw);
    const parsed = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1));
    const answered = parsed.answered === true && String(parsed.reply || '').trim() !== '';
    out = {
      answered,
      reason: String(parsed.reason || (answered ? 'answered from notes' : 'the AI did not answer')),
      // The model's words only ever reach a customer on the path where it said it could answer.
      reply: answered ? String(parsed.reply) : cannot,
      machine_failed: false,
    };
  } catch (e) {
    out = { answered: false, reason: `the AI reply was not readable JSON (${e.message})`,
            reply: cannot, machine_failed: true };
  }
}
return [{ json: { ...turn, ...out } }];

// The turn, written down. Kept per chat, bounded, and emitted so you can send it anywhere you like with one
// more node — a sheet, a CRM, a file — without changing anything above.
const cfg = $('Settings').first().json;
const d = $('Read the AI reply').first().json;
const store = $getWorkflowStaticData('global');
const chat = store.chats[d.chatId];
const at = new Date().toISOString();

chat.turns.push({ at, who: d.who, text: d.text });
chat.turns.push({ at, who: 'bot', text: d.reply, answered: d.answered, reason: d.reason });
const cap = Math.max(20, Number(cfg.log_turns_kept) || 200);
if (chat.turns.length > cap) chat.turns = chat.turns.slice(-cap);

return [{ json: {
  at, chat_id: d.chatId, who: d.who, customer_said: d.text, bot_said: d.reply,
  answered: d.answered, reason: d.reason, machine_failed: !!d.machine_failed, turns_kept: chat.turns.length,
}}];
